create table public.underwriting_operation_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null,job_id uuid,deal_id uuid,event_type text not null,duration_ms integer,cost_microunits bigint,metadata jsonb not null default'{}',created_at timestamptz not null default now(),foreign key(job_id,organization_id)references public.underwriting_jobs(id,organization_id),foreign key(deal_id,organization_id)references public.deals(id,organization_id));
create table public.underwriting_release_certifications(id uuid primary key default gen_random_uuid(),candidate_sha text not null check(candidate_sha~'^[0-9a-f]{40}$'),certification_version text not null check(certification_version='buddy-underwriter-certification.v1'),evidence jsonb not null,status text not null check(status in('failed','release_candidate')),certified_by uuid not null references auth.users(id),certified_at timestamptz not null default now(),unique(candidate_sha,certification_version));
alter table public.underwriting_operation_events enable row level security;alter table public.underwriting_release_certifications enable row level security;revoke all on public.underwriting_operation_events,public.underwriting_release_certifications from public,anon,authenticated;grant select on public.underwriting_operation_events,public.underwriting_release_certifications to authenticated;
create policy "underwriting_events_read" on public.underwriting_operation_events for select to authenticated using(exists(select 1 from public.organization_memberships m where m.organization_id=underwriting_operation_events.organization_id and m.user_id=auth.uid() and m.is_active));create policy "underwriting_certifications_admin_read" on public.underwriting_release_certifications for select to authenticated using(exists(select 1 from public.organization_memberships m where m.user_id=auth.uid() and m.is_active and m.role in('owner','administrator')));
comment on table public.underwriting_release_certifications is 'Evidence ledger only. release_candidate never means production active; activation remains external and human authorized.';
